-- Dummy data for testing only. Load into an empty database (after schema.sql).
-- No schema changes: only INSERTs. Dates are relative to today, so 'this month' and 'next month' questions always return data.
--
-- How the real-world structure maps onto the existing tables:
--   Region -> locations.description ('Region: KZN | Site: Umhlanga')
--   Site/building -> locations.building (e.g. 'Umhlanga Building 2')
--   Floor -> locations.floor ('G', '1', '2', '3'); each floor is its own locations row
--   Spare/retired stock lives in an 'IT Storeroom' row per site
--   Shared items (printers, TVs, meeting-room tablets) are assigned to a custodian on that floor
-- New asset types 9-13 are added as data. Needs asset_types_asset_type_id_seq at 8 (as in schema.sql).
BEGIN;
-- Current assignments: issued 5 days after purchase (capped at now)
SELECT a.asset_id, a.assigned_to_user_id, LEAST(CURRENT_TIMESTAMP, a.purchase_date::timestamptz + interval '5 days'), NULL, CASE l.description WHEN 'Region: KZN | Site: Umhlanga' THEN 1 WHEN 'Region: Gauteng | Site: Johannesburg' THEN 38 ELSE 44 END, 'Issued'
FROM asset_management.assets a JOIN asset_management.locations l ON l.location_id = a.location_id
WHERE a.assigned_to_user_id IS NOT NULL AND a.asset_id NOT IN (103, 109, 117, 119, 124, 199, 201, 237);
-- Returned and reissued items (previous holders are leavers)
SELECT asset_id, 'Registered', NULL, asset_no, 1, COALESCE(purchase_date::timestamptz, created_date) FROM asset_management.assets;
SELECT aa.asset_id, 'Assigned', NULL, u.first_name || ' ' || u.last_name, aa.assigned_by_user_id, aa.assigned_date
FROM asset_management.asset_assignments aa JOIN asset_management.users u ON u.user_id = aa.user_id;
SELECT aa.asset_id, 'Returned', u.first_name || ' ' || u.last_name, NULL, aa.assigned_by_user_id, aa.returned_date
FROM asset_management.asset_assignments aa JOIN asset_management.users u ON u.user_id = aa.user_id
WHERE aa.returned_date IS NOT NULL;
COMMIT;
